func interfaceEthernetBasePath(name string) []any {
	return []any{"interfaces", "ethernet", name}
}

// Create sets up the InterfaceEthernet on VyOS.
func (InterfaceEthernet) Create(
	ctx context.Context,
	req infer.CreateRequest[InterfaceEthernetArgs],
) (infer.CreateResponse[InterfaceEthernetState], error) {
	if req.DryRun {
		return infer.CreateResponse[InterfaceEthernetState]{
			ID:     req.Inputs.Name,
			Output: InterfaceEthernetState{InterfaceEthernetArgs: req.Inputs},
		}, nil
	}

	ops := buildInterfaceEthernetOps(req.Inputs)
	client := getClient(ctx)
	if err := client.BatchConfigure(ctx, ops); err != nil {
		return infer.CreateResponse[InterfaceEthernetState]{},
			fmt.Errorf("configure InterfaceEthernet %s: %w", req.Inputs.Name, err)
	}
	saveIfEnabled(ctx)

	return infer.CreateResponse[InterfaceEthernetState]{
		ID:     req.Inputs.Name,
		Output: InterfaceEthernetState{InterfaceEthernetArgs: req.Inputs},
	}, nil
}

// Read fetches the current InterfaceEthernet config from VyOS.
func (InterfaceEthernet) Read(
	ctx context.Context,
	req infer.ReadRequest[InterfaceEthernetArgs, InterfaceEthernetState],
) (infer.ReadResponse[InterfaceEthernetArgs, InterfaceEthernetState], error) {
	client := getClient(ctx)
	base := interfaceEthernetBasePath(req.State.Name)

	data, err := client.ShowConfig(ctx, pathToStrings(base))
	if err != nil {
		if isEmptyConfigError(err) {
			// Tag node exists but has no child properties. Return minimal state.
			args := InterfaceEthernetArgs{Name: req.State.Name}
			state := InterfaceEthernetState{InterfaceEthernetArgs: args}
			return infer.ReadResponse[InterfaceEthernetArgs, InterfaceEthernetState]{
				ID:     req.State.Name,
				Inputs: args,
				State:  state,
			}, nil
		}
		return infer.ReadResponse[InterfaceEthernetArgs, InterfaceEthernetState]{},
			fmt.Errorf("read InterfaceEthernet %s: %w", req.State.Name, err)
	}

	args, err := parseInterfaceEthernetConfig(req.State.Name, data)
	if err != nil {
		return infer.ReadResponse[InterfaceEthernetArgs, InterfaceEthernetState]{},
			fmt.Errorf("parse InterfaceEthernet %s config: %w", req.State.Name, err)
	}

	state := InterfaceEthernetState{InterfaceEthernetArgs: args}
	return infer.ReadResponse[InterfaceEthernetArgs, InterfaceEthernetState]{
		ID:     req.State.Name,
		Inputs: args,
		State:  state,
	}, nil
}

// Update modifies an existing InterfaceEthernet configuration.
func (InterfaceEthernet) Update(
	ctx context.Context,
	req infer.UpdateRequest[InterfaceEthernetArgs, InterfaceEthernetState],
) (infer.UpdateResponse[InterfaceEthernetState], error) {
	if req.DryRun {
		return infer.UpdateResponse[InterfaceEthernetState]{
			Output: InterfaceEthernetState{InterfaceEthernetArgs: req.Inputs},
		}, nil
	}

	ops := buildInterfaceEthernetUpdateOps(req.State.InterfaceEthernetArgs, req.Inputs)
	if len(ops) > 0 {
		client := getClient(ctx)
		if err := client.BatchConfigure(ctx, ops); err != nil {
			return infer.UpdateResponse[InterfaceEthernetState]{},
				fmt.Errorf("update InterfaceEthernet %s: %w", req.Inputs.Name, err)
		}
		saveIfEnabled(ctx)
	}

	return infer.UpdateResponse[InterfaceEthernetState]{
		Output: InterfaceEthernetState{InterfaceEthernetArgs: req.Inputs},
	}, nil
}

// Delete removes the InterfaceEthernet configuration from VyOS.
func (InterfaceEthernet) Delete(
	ctx context.Context,
	req infer.DeleteRequest[InterfaceEthernetState],
) (infer.DeleteResponse, error) {
	client := getClient(ctx)
	base := interfaceEthernetBasePath(req.State.Name)
	if err := client.Delete(ctx, pathToStrings(base)); err != nil {
		return infer.DeleteResponse{}, fmt.Errorf("delete InterfaceEthernet %s: %w", req.State.Name, err)
	}
	saveIfEnabled(ctx)
	return infer.DeleteResponse{}, nil
}

